import{_ as a,o as n,c as s,a2 as e}from"./chunks/framework.BbQrW5_t.js";const c=JSON.parse('{"title":"《AI Agent 实战》后记 知识笔记","description":"","frontmatter":{},"headers":[],"relativePath":"study/ai-agent-book/11-afterword.md","filePath":"study/ai-agent-book/11-afterword.md","lastUpdated":1785465991000}'),r={name:"study/ai-agent-book/11-afterword.md"};function l(d,t,o,i,h,p){return n(),s("div",null,[...t[0]||(t[0]=[e(`<h1 id="《ai-agent-实战》后记-知识笔记" tabindex="-1">《AI Agent 实战》后记 知识笔记 <a class="header-anchor" href="#《ai-agent-实战》后记-知识笔记" aria-label="Permalink to &quot;《AI Agent 实战》后记 知识笔记&quot;">​</a></h1><hr><h2 id="一、核心公式-agent-llm-上下文-工具" tabindex="-1">一、核心公式：Agent = LLM + 上下文 + 工具 <a class="header-anchor" href="#一、核心公式-agent-llm-上下文-工具" aria-label="Permalink to &quot;一、核心公式：Agent = LLM + 上下文 + 工具&quot;">​</a></h2><p>这是全书的核心框架，三个要素缺一不可：</p><table tabindex="0"><thead><tr><th>要素</th><th>含义</th></tr></thead><tbody><tr><td><strong>LLM</strong></td><td>大语言模型，提供核心推理能力</td></tr><tr><td><strong>上下文</strong></td><td>Agent 看到的信息，决定&quot;知道什么&quot;</td></tr><tr><td><strong>工具</strong></td><td>Agent 能执行的动作，决定&quot;能做什么&quot;</td></tr></tbody></table><p>三个维度理解：</p><ul><li><strong>实现层</strong>：技术实现的角度</li><li><strong>直觉层</strong>：功能感知的角度</li><li><strong>学术层</strong>：理论研究的角度</li></ul><hr><h2 id="二、全书结构-构建-→-评估-→-协作" tabindex="-1">二、全书结构：构建 → 评估 → 协作 <a class="header-anchor" href="#二、全书结构-构建-→-评估-→-协作" aria-label="Permalink to &quot;二、全书结构：构建 → 评估 → 协作&quot;">​</a></h2><h3 id="_2-1-构建-agent-第2-5章" tabindex="-1">2.1 构建 Agent（第2-5章） <a class="header-anchor" href="#_2-1-构建-agent-第2-5章" aria-label="Permalink to &quot;2.1 构建 Agent（第2-5章）&quot;">​</a></h3><table tabindex="0"><thead><tr><th>章节</th><th>主题</th><th>核心内容</th></tr></thead><tbody><tr><td>第2章</td><td>上下文工程</td><td>决定Agent在一次任务中看到什么</td></tr><tr><td>第3章</td><td>记忆与知识库</td><td>把信息扩展到多次会话</td></tr><tr><td>第4章</td><td>工具</td><td>定义Agent能做什么</td></tr><tr><td>第5章</td><td>代码生成</td><td>创造新工具与新系统的元能力</td></tr></tbody></table><h3 id="_2-2-评估与进化-第6-8章" tabindex="-1">2.2 评估与进化（第6-8章） <a class="header-anchor" href="#_2-2-评估与进化-第6-8章" aria-label="Permalink to &quot;2.2 评估与进化（第6-8章）&quot;">​</a></h3><table tabindex="0"><thead><tr><th>章节</th><th>主题</th><th>核心内容</th></tr></thead><tbody><tr><td>第6章</td><td>评估</td><td>把表现变成可信信号</td></tr><tr><td>第7章</td><td>后训练</td><td>把高维能力写入模型参数</td></tr><tr><td>第8章</td><td>持续进化</td><td>把生产经验转化为知识/指令/程序/参数的受控更新</td></tr></tbody></table><blockquote><p>第八章是全书的汇合点：从&quot;怎样构建Agent&quot;转向&quot;怎样让Agent长期变好&quot;</p></blockquote><h3 id="_2-3-交互与协作-第9-10章" tabindex="-1">2.3 交互与协作（第9-10章） <a class="header-anchor" href="#_2-3-交互与协作-第9-10章" aria-label="Permalink to &quot;2.3 交互与协作（第9-10章）&quot;">​</a></h3><table tabindex="0"><thead><tr><th>章节</th><th>主题</th><th>核心内容</th></tr></thead><tbody><tr><td>第9章</td><td>多模态与实时交互</td><td>扩展感知和行动到语音、GUI、物理世界</td></tr><tr><td>第10章</td><td>多Agent协作</td><td>改变上下文、工具与责任的组织方式</td></tr></tbody></table><hr><h2 id="三、两朵乌云-agent-发展的两大挑战" tabindex="-1">三、两朵乌云：Agent 发展的两大挑战 <a class="header-anchor" href="#三、两朵乌云-agent-发展的两大挑战" aria-label="Permalink to &quot;三、两朵乌云：Agent 发展的两大挑战&quot;">​</a></h2><h3 id="_3-1-第一朵乌云-实时交互" tabindex="-1">3.1 第一朵乌云：实时交互 <a class="header-anchor" href="#_3-1-第一朵乌云-实时交互" aria-label="Permalink to &quot;3.1 第一朵乌云：实时交互&quot;">​</a></h3><p><strong>问题</strong>：当前Agent是&quot;请求-应答&quot;模式，无法边听边想、边说边想</p><p><strong>两条解决路径</strong>：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>┌─────────────────────────────────────────────────────────────┐</span></span>
<span class="line"><span>│ 路径一：架构上做快慢分离                                      │</span></span>
<span class="line"><span>│   • 前台快模型：维持对话节奏                                   │</span></span>
<span class="line"><span>│   • 后台慢模型：负责深度思考                                   │</span></span>
<span class="line"><span>├─────────────────────────────────────────────────────────────┤</span></span>
<span class="line"><span>│ 路径二：把推理本身做快                                        │</span></span>
<span class="line"><span>│   • 小米MiMo：1T参数模型达1000+ token/s                       │</span></span>
<span class="line"><span>│   • Taalas HC1：80亿参数模型达17000 token/s，响应&lt;100ms        │</span></span>
<span class="line"><span>└─────────────────────────────────────────────────────────────┘</span></span></code></pre></div><p><strong>核心洞见</strong>：当生成速度足够快，&quot;想完再说&quot;和&quot;边想边说&quot;的体验差距就被抹平了</p><h3 id="_3-2-第二朵乌云-持续学习" tabindex="-1">3.2 第二朵乌云：持续学习 <a class="header-anchor" href="#_3-2-第二朵乌云-持续学习" aria-label="Permalink to &quot;3.2 第二朵乌云：持续学习&quot;">​</a></h3><p><strong>问题</strong>：模型训练后几乎不再成长，经验随着上下文被丢弃</p><p><strong>两种假设对比</strong>：</p><table tabindex="0"><thead><tr><th>假设</th><th>观点</th><th>含义</th></tr></thead><tbody><tr><td><strong>小世界假设</strong></td><td>大模型能装下几乎所有通用知识</td><td>瓶颈在于数据，训练一次即可</td></tr><tr><td><strong>大世界假设</strong></td><td>用户/公司的具体知识不在训练语料中</td><td>需要上岗后持续学习</td></tr></tbody></table><p><strong>持续学习的方式</strong>：</p><ul><li>把经验写成知识文档</li><li>转化为指令或程序</li><li>经过筛选后更新模型参数</li></ul><hr><h2 id="四、模型与-agent-的共同演进" tabindex="-1">四、模型与 Agent 的共同演进 <a class="header-anchor" href="#四、模型与-agent-的共同演进" aria-label="Permalink to &quot;四、模型与 Agent 的共同演进&quot;">​</a></h2><h3 id="_4-1-自我强化的飞轮" tabindex="-1">4.1 自我强化的飞轮 <a class="header-anchor" href="#_4-1-自我强化的飞轮" aria-label="Permalink to &quot;4.1 自我强化的飞轮&quot;">​</a></h3><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>用户提出真实难题</span></span>
<span class="line"><span>      ↓</span></span>
<span class="line"><span>应用层用Harness暂时补上模型做不好的事</span></span>
<span class="line"><span>      ↓</span></span>
<span class="line"><span>这些补救沉淀成训练信号</span></span>
<span class="line"><span>      ↓</span></span>
<span class="line"><span>下一代模型内化这些能力</span></span>
<span class="line"><span>      ↓</span></span>
<span class="line"><span>对应的Harness代码可以删掉</span></span>
<span class="line"><span>      ↓</span></span>
<span class="line"><span>（循环继续）</span></span></code></pre></div><h3 id="_4-2-harness-的命运" tabindex="-1">4.2 Harness 的命运 <a class="header-anchor" href="#_4-2-harness-的命运" aria-label="Permalink to &quot;4.2 Harness 的命运&quot;">​</a></h3><p><strong>模型会吃掉 Harness 吗？</strong></p><p>答案：会，一层一层地吃，但永远不会完结</p><p><strong>原因</strong>：</p><ol><li>训练以月计，模型等得起，业务等不起</li><li>模型无法内化所有业务约束与偏好</li><li>每代模型都会打开新的能力前沿</li></ol><blockquote><p><strong>《苦涩的教训》在Agent时代的读法</strong>：通用方法终将胜出，但&quot;终将&quot;二字里的每一段路，都是Harness铺出来的</p></blockquote><h3 id="_4-3-护城河的本质" tabindex="-1">4.3 护城河的本质 <a class="header-anchor" href="#_4-3-护城河的本质" aria-label="Permalink to &quot;4.3 护城河的本质&quot;">​</a></h3><p><strong>对造模型的人</strong>：把飞轮转起来，让真实场景的反馈尽快回流到训练里</p><p><strong>对造应用的人</strong>：</p><ul><li>Harness 是短期最锋利的技术杠杆</li><li>但要清醒：模型会内化约束，抹平只靠 Harness 的优势</li><li>真正的长久护城河在技术之外： <ul><li>独占的数据</li><li>稳固的渠道</li><li>用户的信任</li><li>网络效应</li><li>人与Agent协作的复杂场景</li></ul></li></ul><hr><h2 id="五、三个不会过时的问题" tabindex="-1">五、三个不会过时的问题 <a class="header-anchor" href="#五、三个不会过时的问题" aria-label="Permalink to &quot;五、三个不会过时的问题&quot;">​</a></h2><p>无论模型如何迭代，这三个问题永不过时：</p><table tabindex="0"><thead><tr><th>问题</th><th>对应要素</th></tr></thead><tbody><tr><td>看到什么</td><td>上下文</td></tr><tr><td>能做什么</td><td>工具</td></tr><tr><td>如何验证做得对不对</td><td>评估</td></tr></tbody></table><blockquote><p>这些问题描述的是一个智能系统与世界交互的基本方式</p></blockquote><hr><h2 id="六、关键洞见与金句" tabindex="-1">六、关键洞见与金句 <a class="header-anchor" href="#六、关键洞见与金句" aria-label="Permalink to &quot;六、关键洞见与金句&quot;">​</a></h2><ol><li><p><strong>Harness的本质</strong>：每一层兜底逻辑都记录着模型此刻还做不稳的地方</p></li><li><p><strong>飞轮的力量</strong>：真实业务、反馈数据与模型迭代咬合得越紧，别人越难从外部追上</p></li><li><p><strong>最深的护城河</strong>：同时握住模型和Harness两端，让它们互相喂养、共同进化</p></li><li><p><strong>应用层的策略</strong>：把Harness用来争取时间，用这段时间构筑技术之外的壁垒</p></li><li><p><strong>学习的本质</strong>：模型最强的能力，终将不是记住，而是学习与适应</p></li></ol><hr><h2 id="七、行动建议" tabindex="-1">七、行动建议 <a class="header-anchor" href="#七、行动建议" aria-label="Permalink to &quot;七、行动建议&quot;">​</a></h2><ol><li><p><strong>亲手实践</strong>：读懂和做出来之间，隔着一条只能靠双手跨过的河</p></li><li><p><strong>保持清醒</strong>：掌握判断力，而非某个API的具体用法</p></li><li><p><strong>去创造</strong>：Agent能通过写代码创造新的能力，甚至改进自己</p></li></ol><hr><h2 id="八、技术参考" tabindex="-1">八、技术参考 <a class="header-anchor" href="#八、技术参考" aria-label="Permalink to &quot;八、技术参考&quot;">​</a></h2><table tabindex="0"><thead><tr><th>技术</th><th>描述</th><th>速度</th></tr></thead><tbody><tr><td>小米 MiMo-V2.5-Pro-UltraSpeed</td><td>1T参数模型，FP4量化 + DFlash并行推测解码</td><td>&gt;1000 token/s</td></tr><tr><td>Taalas HC1</td><td>Llama 3.1 8B 固化进6nm芯片</td><td>~17000 token/s，响应&lt;100ms</td></tr></tbody></table><hr><p><em>整理时间：2026年7月31日</em></p>`,59)])])}const b=a(r,[["render",l]]);export{c as __pageData,b as default};
